const now = new Date();

for (const [userId, data] of Object.entries(userData)) {
  if (!data.leadMagnetAt) continue;

  const daysSince = (now - new Date(data.leadMagnetAt)) / (1000*60*60*24);

  // Day 1: Case study
  if (daysSince >= 1 && daysSince < 1.5 && !data.sentDay1) {
    data.sentDay1 = true;
